import subprocess

# Read the current server.js from container 111
r = subprocess.run(
    ["pct", "exec", "111", "--", "cat", "/opt/control-panel-backend/server.js"],
    capture_output=True, text=True,
)
current = r.stdout
if not current:
    raise SystemExit(f"failed to read server.js: {r.stderr.strip()}")

# Backup
subprocess.run(
    ["pct", "exec", "111", "--", "cp", "-a",
     "/opt/control-panel-backend/server.js",
     "/opt/control-panel-backend/server.js.bak.palworld"],
    check=True,
)

# The route code to append before the final app.listen line
route_code = '''
// Palworld settings capability: read/write the server's own settings file
const PALWORLD_IP = "192.168.1.106";
const PALWORLD_USER = "aedefruscio";
const PALWORLD_CONFIG = "/opt/palworld/Pal/Saved/Config/LinuxServer/PalWorldSettings.ini";
const PALWORLD_SERVICE = "palworld.service";

function parsePalworldSettings(text) {
  const settings = {};
  const match = text.match(/OptionSettings=\\(([^)]*)\\)/);
  if (!match) return settings;
  const pairs = match[1].split(",");
  for (const pair of pairs) {
    const idx = pair.indexOf("=");
    if (idx === -1) continue;
    const key = pair.slice(0, idx).trim();
    const value = pair.slice(idx + 1).trim();
    settings[key] = value;
  }
  return settings;
}

function serializePalworldSettings(settings) {
  const pairs = Object.entries(settings).map(([k, v]) => `${k}=${v}`);
  return `OptionSettings=(${pairs.join(",")})`;
}

function palworldSsh(args) {
  return new Promise((resolve, reject) => {
    const { execFile } = require("child_process");
    execFile(
      "ssh",
      ["-o", "BatchMode=yes", "-o", "StrictHostKeyChecking=yes",
       `${PALWORLD_USER}@${PALWORLD_IP}`, ...args],
      { timeout: 30000 },
      (err, stdout, stderr) => {
        if (err) reject(new Error(stderr || err.message));
        else resolve(stdout);
      }
    );
  });
}

app.get("/api/palworld/settings", async (req, res) => {
  try {
    const text = await palworldSsh(["cat", PALWORLD_CONFIG]);
    res.json(parsePalworldSettings(text));
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

app.put("/api/palworld/settings", async (req, res) => {
  try {
    const newSettings = req.body;
    if (!newSettings || typeof newSettings !== "object") {
      return res.status(400).json({ error: "body must be a settings object" });
    }
    const text = await palworldSsh(["cat", PALWORLD_CONFIG]);
    const current = parsePalworldSettings(text);
    const merged = { ...current, ...newSettings };
    const newLine = serializePalworldSettings(merged);
    const newText = text.replace(/OptionSettings=\\([^)]*\\)/, newLine);
    const writeCmd = [
      "sudo", "-S", "-p", "", "bash", "-c",
      `systemctl stop ${PALWORLD_SERVICE} && ` +
      `printf '%s\\\\n' '${newText.replace(/'/g, "'\\\\''")}' > ${PALWORLD_CONFIG} && ` +
      `systemctl start ${PALWORLD_SERVICE}`,
    ];
    await palworldSsh(writeCmd);
    res.json(merged);
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});
'''

# Insert the route code before the final app.listen line
lines = current.split("\n")
insert_idx = None
for i in range(len(lines) - 1, -1, -1):
    if "app.listen" in lines[i]:
        insert_idx = i
        break

if insert_idx is None:
    raise SystemExit("could not find app.listen in server.js")

new_lines = lines[:insert_idx] + [route_code] + lines[insert_idx:]
new_content = "\n".join(new_lines)

# Write the new server.js back to container 111
r = subprocess.run(
    ["pct", "exec", "111", "--", "tee", "/opt/control-panel-backend/server.js"],
    input=new_content, capture_output=True, text=True,
)
if r.returncode != 0:
    raise SystemExit(f"failed to write server.js: {r.stderr.strip()}")

print("route added to server.js")
